script:
out = {}
for p in ["src/a.txt", "src/nested/b.txt", "docs/history.txt"]:
    out[p] = repo.read(p)

# also list all files under src
files = []
def walk(path):
    for name in repo.list(path):
        full = path.rstrip("/") + "/" + name
        if name.endswith("/"):
            walk(full)
        else:
            files.append(full)
walk("src")

result({"files_under_src": files, "contents": out})

for p in ["src/a.txt", "src/nested/b.txt", "src/untouched.txt"]:
    content = repo.read(p)
    new = content.replace("slow_path", "fast_path")
    if new != content:
        repo.write(p, new)

result({"diff": repo.diff(), "status": [{"path": s.path, "kind": s.kind} for s in repo.status()]})

